-- Workspaces (Better Auth organization plugin) and content scoped by workspace.
-- Generated by drizzle-kit, then edited by hand: SQLite cannot add a NOT NULL
-- foreign key column to a table with rows, so content_item is rebuilt, and the
-- existing data moves into the "Signum" workspace.
CREATE TABLE `invitation` (
	`id` text PRIMARY KEY,
	`organization_id` text NOT NULL,
	`email` text NOT NULL,
	`role` text,
	`status` text DEFAULT 'pending' NOT NULL,
	`expires_at` integer NOT NULL,
	`created_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL,
	`inviter_id` text NOT NULL,
	CONSTRAINT `fk_invitation_organization_id_organization_id_fk` FOREIGN KEY (`organization_id`) REFERENCES `organization`(`id`) ON DELETE CASCADE,
	CONSTRAINT `fk_invitation_inviter_id_user_id_fk` FOREIGN KEY (`inviter_id`) REFERENCES `user`(`id`) ON DELETE CASCADE
);
--> statement-breakpoint
CREATE TABLE `member` (
	`id` text PRIMARY KEY,
	`organization_id` text NOT NULL,
	`user_id` text NOT NULL,
	`role` text DEFAULT 'member' NOT NULL,
	`created_at` integer NOT NULL,
	CONSTRAINT `fk_member_organization_id_organization_id_fk` FOREIGN KEY (`organization_id`) REFERENCES `organization`(`id`) ON DELETE CASCADE,
	CONSTRAINT `fk_member_user_id_user_id_fk` FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON DELETE CASCADE
);
--> statement-breakpoint
CREATE TABLE `organization` (
	`id` text PRIMARY KEY,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`logo` text,
	`created_at` integer NOT NULL,
	`metadata` text
);
--> statement-breakpoint
ALTER TABLE `session` ADD `active_organization_id` text;
--> statement-breakpoint
-- Existing users and content become the "Signum" workspace (only when there
-- are users, so a fresh database starts empty). The first user to sign up is
-- its owner; anyone else joins as a member.
INSERT INTO `organization` (`id`, `name`, `slug`, `created_at`)
SELECT 'a6f3c1d2-5b7e-4c39-9f0a-2e8d4b6c1a57', 'Signum', 'signum', cast(unixepoch('subsecond') * 1000 as integer)
WHERE EXISTS (SELECT 1 FROM `user`);
--> statement-breakpoint
INSERT INTO `member` (`id`, `organization_id`, `user_id`, `role`, `created_at`)
SELECT
	lower(hex(randomblob(16))),
	'a6f3c1d2-5b7e-4c39-9f0a-2e8d4b6c1a57',
	`id`,
	CASE WHEN `id` = (SELECT `id` FROM `user` ORDER BY `created_at`, `id` LIMIT 1) THEN 'owner' ELSE 'member' END,
	cast(unixepoch('subsecond') * 1000 as integer)
FROM `user`;
--> statement-breakpoint
UPDATE `session` SET `active_organization_id` = 'a6f3c1d2-5b7e-4c39-9f0a-2e8d4b6c1a57'
WHERE EXISTS (SELECT 1 FROM `organization` WHERE `id` = 'a6f3c1d2-5b7e-4c39-9f0a-2e8d4b6c1a57');
