-- Rebuild content_item with organization_id. content_asset references it, and
-- dropping a referenced table would cascade-delete those rows, so the asset
-- rows are parked in a plain table first and restored afterwards.
CREATE TABLE `__content_asset_backup` AS SELECT * FROM `content_asset`;
--> statement-breakpoint
DROP TABLE `content_asset`;
